const workload = JSON.parse(readFileSync(resolve('tests/fixtures/cli-regression/runtime-workload-g1e.json'), 'utf8'))
const helper = (python: string, args: string[]): string => execFileSync(python, ['-m', 'tests.cli_regression.support.g1e.helper', ...args], { cwd: resolve('backend'), encoding: 'utf8', timeout: 60_000, maxBuffer: 64 * 1024 * 1024 })
const sha256 = (data: Buffer | string): string => createHash('sha256').update(data).digest('hex')
const unix = (path: string) => (payload: Record<string, unknown>): Promise<any> => new Promise((resolveReply, reject) => {
  const socket = net.connect(path)
  let buffer = ''
  const timer = setTimeout(() => { socket.destroy(); reject(new Error('counters socket deadline')) }, workload.deadlineMs)
  socket.on('data', (chunk) => {
    buffer += chunk
    if (buffer.endsWith('\n')) { clearTimeout(timer); socket.end(); resolveReply(JSON.parse(buffer)) }
  })
  socket.on('error', (error) => { clearTimeout(timer); reject(error) })
  socket.write(`${JSON.stringify(payload)}\n`)
})

const counters = (raw: Record<string, unknown>): { read_total: number; emitted_total: number; dropped_oldest_total: number } => {
  const { read_total, emitted_total, dropped_oldest_total } = raw as Record<string, number>
  if (![read_total, emitted_total, dropped_oldest_total].every((value) => Number.isInteger(value) && value >= 0)) throw new Error(`counters snapshot is not three counts: ${JSON.stringify(raw).slice(0, 120)}`)
  return { read_total, emitted_total, dropped_oldest_total }
}

/**
 * The receipts of the runtime generation the FIRST backend owns, in the shape the 06 proof reads. E3's per-session records carry no `runtime_generation`; they take the generation they sit in.
 * The E3 ready receipt names its identity as `protocol: 'navide-acr', wire: 1, handoff: 'scm_rights'` (E1 v8b), where the 06 checker expects `protocol: 1`: the E3 identity is verified HERE
 * (a mismatch is left untouched so the 06 check rejects it) and only then presented to the unchanged 06 checker in its own vocabulary.
 */
export function firstGenerationReceipts(receipts: Array<Record<string, any>>, backendPid: number): Array<Record<string, any>> {
  const ready = receipts.find((entry) => entry.event === 'ready' && entry.owner_pid === backendPid)
  if (!ready) return receipts.filter((entry) => entry.event !== 'ready')
  const generation = ready.runtime_generation
  const identityOk = ready.protocol === 'navide-acr' && ready.wire === 2 && ready.handoff === 'scm_rights'
  return receipts
    .filter((entry) => entry === ready || (entry.event !== 'ready' && (entry.runtime_generation ?? generation) === generation))
    .map((entry) => (entry === ready ? (identityOk ? { ...entry, protocol: 1 } : entry) : { ...entry, runtime_generation: generation }))
}

/**
 * Ambient state only (no process names or argv): the numbers of the host record (E2 v14-r2 V19 item 5: the clock, the load averages, the CPU count and the process count, the line count
 * of `ps -A -o pid=`) and the power source and thermal limit lines. Taken at the existing before/after points only, never inside a measured phase; information only.
 */
export function ambientSnapshot(): Record<string, unknown> {
  const run = (args: string[]): string => {
    try { return execFileSync('pmset', args, { timeout: 5000, encoding: 'utf8' }).split('\n').filter((line) => /Now drawing|Speed_Limit|thermal/i.test(line)).join(' | ') } catch (error) { return `unavailable: ${boundedErrorCode(error)}` }
  }
  const ps = (): string => { try { return execFileSync('ps', ['-A', '-o', 'pid='], { timeout: 5000, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 }) } catch { return '' } }
  return { ...hostNumbers({ now: Date.now, loadavg, ncpu: () => cpus().length, ps }), power: run(['-g', 'batt']), thermal: run(['-g', 'therm']) }
}

/** Process start time as the OS reports it: the same string at the start and at the end of the attempt (isolation proof, E2 section 3 item 7). */
function processStart(pid: number): string {
  try { return execFileSync('ps', ['-o', 'lstart=', '-p', String(pid)], { encoding: 'utf8', timeout: 5000 }).trim() } catch { return '' }
}

async function untilFile(path: string, message: string, timeout: number, isDead: () => string | null): Promise<void> {
  const deadline = performance.now() + timeout // a failure bound; the 20 ms step only separates file-existence checks, it is no measurement
  while (!existsSync(path)) {
    const dead = isDead()
    if (dead) throw new Error(`${message}: ${dead}`)
    if (performance.now() >= deadline) throw new Error(message)
    await delay(20)
  }
}

type Peer = { pane: string; vendor: string; workspace: string; command: string[]; argv: string[]; wrapped: boolean; commandLine: string; index: number; logPath: string | null }
type Running = Peer & { tid: string; pid: number; sessionId: string; nonce: string; stream: StreamBuffer; burst: BurstTracker; inodeAtCreate: [number, number]; origin: { counters: any; stable: boolean } | null; exitAt: number | null; deadSeenAt: number | null; finalSeen: boolean }
type Sample = ProofSample & { generation: string; backend: { pid: number; created: number } }

export async function runAttempt(spec: AttemptSpec, reports: string): Promise<AttemptResult> {
  const { mode, count, repeat } = spec
  const failures: string[] = []
  const root = realpathSync(mkdtempSync(join(tmpdir(), 'navide-g1e-')))
  const ambientBefore = ambientSnapshot()
  const started = performance.now()
  const driver = spawn(spec.python, ['-m', 'tests.cli_regression.support.g1e.driver', root, String(count), String(repeat), mode], {
    cwd: resolve('backend'), stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true,
    env: { ...process.env, ...(spec.sidecarBin ? { ACR_SIDECAR_BIN: spec.sidecarBin } : {}) },
  })
  let log = ''
  let exitCode: number | null | undefined
  driver.stdout.on('data', (chunk) => { log += chunk })
  driver.stderr.on('data', (chunk) => { log += chunk })
  driver.on('error', (error) => { log += error.message; exitCode = -1 })
  driver.on('exit', (code) => { exitCode = code; waiter.notify() })
  const waiter = new ArrivalWaiter()
  let connections = 0
  const client = createWsClient({ onStatus: (status) => { if (status === 'connected') { connections++; waiter.notify() } } })
  const exitEvents: Array<{ tid: string; wallMs: number; reason: string; exitCode: unknown }> = []
  const events: Array<{ type: string; payload: Record<string, unknown>; wallMs: number; at: number }> = []
  const streams = new Map<string, Running>()
  for (const type of ['agent.activity', 'session.detected', 'terminal.exit']) {
    client.on(type, (payload) => {
      const at = performance.now()
      const event = { type, payload: payload as Record<string, unknown>, wallMs: Date.now(), at }
      events.push(event)
      if (type === 'terminal.exit') { const body = payload as Record<string, unknown>; exitEvents.push({ tid: String(body.terminal_session_id), wallMs: event.wallMs, reason: String(body.reason), exitCode: body.exit_code ?? null }); const peer = streams.get(String((payload as Record<string, unknown>).terminal_session_id)); if (peer && peer.exitAt === null) peer.exitAt = event.wallMs }
      waiter.notify()
    })
  }
  const lastArrival = new Map<string, number>()
  client.on('terminal.output', (payload) => {
    const at = performance.now()
    const frame = payload as TerminalOutputFrame
    const tid = frame.terminal_session_id
    // Every created terminal has a buffer (shells included); `streamOf` makes it on first sight so a chunk before the create reply is never lost.
    const stream = streamOf(tid)
    const monotonic = Math.max(at, (lastArrival.get(tid) ?? -Infinity) + 1e-6)
    lastArrival.set(tid, monotonic)
    stream.onChunk(monotonic, frame.data)
  })
  const shellStreams = new Map<string, StreamBuffer>()
  function streamOf(tid: string): StreamBuffer {
    const running = streams.get(tid)
    if (running) return running.stream
    let stream = shellStreams.get(tid)
    if (!stream) { stream = new StreamBuffer(); shellStreams.set(tid, stream) }
    return stream
  }
  const latencies: Record<string, number[]> = {}
  const phases: Array<{ name: string; wallMs: number }> = [{ name: 'cold_startup', wallMs: Date.now() }]
  const phaseOutcomes: Record<string, string> = { cold_startup: 'running' }
  const observationOutcomes: Array<{ pane: string; vendor: string; kind: string; status: string; latencyMs?: number }> = []
  const baselineWarnings: string[] = []
  const tokenSnapshots: Record<string, unknown> = {}
  const mark = (name: string): void => {
    const previous = phases.at(-1)!.name
    if (phaseOutcomes[previous] === 'running') phaseOutcomes[previous] = 'passed'
    phases.push({ name, wallMs: Date.now() })
    phaseOutcomes[name] = name === 'finished' ? 'passed' : 'running'
  }
  const record = (name: string, value: number): void => { (latencies[name] ??= []).push(value) }
  const required = (peer: Peer): boolean => peer.vendor === 'claude' // OpenCode observation is informational (E2 v10 section 2): recorded, never a failure of the trial
  const observationFailure = (peer: Peer, kind: string, error: unknown): void => {
    const message = redactDiagnostic(error instanceof Error ? error.message : String(error))
    observationOutcomes.push({ pane: peer.pane, vendor: peer.vendor, kind, status: message.endsWith('deadline') ? 'censored' : 'failed' })
    if (required(peer)) { phaseOutcomes.observation = 'failed'; failures.push(`${mode}/${count}/${repeat}: ${peer.vendor} ${kind}: ${message}`) }
  }
  async function request<T = Record<string, unknown>>(type: string, payload: Record<string, unknown>): Promise<T> {
    const response = await client.send<T>(type, payload, workload.deadlineMs)
    if (!response.ok) throw new Error(`${type} refused: ${JSON.stringify(response).slice(0, 200)}`)
    return response.payload!
  }
  const createdTerminals: ProofTerminal[] = []
  const identifiedSessions = new Map<string, string>()
  let peers: Running[] = []
  let proof: ReturnType<typeof checkRuntimeProof> | null = null
  let passed = false
  let evidenceValid = false
  let failure: string | null = null
  let stopReason: 'toolchain-mismatch' | null = null
  let readyCheck: ReadyVersionCheck | null = null
  let backendStart = ''
  let backendEnd = ''
  let backendPid = 0
  let logFinals: unknown[] = []
  let ledgers: unknown[] = []
  let controlLedger: unknown = null
  let ckProof: Record<string, any> | null = null
  let countersCall: (payload: Record<string, unknown>) => Promise<any> = async () => { throw new Error('counters socket unknown') }
  const sessions: string[] = []
  try {
    await untilFile(join(root, 'endpoint.json'), 'backend readiness deadline', 60_000, () => (exitCode !== undefined ? `driver exited: ${log}` : null))
    const endpoint = JSON.parse(readFileSync(join(root, 'endpoint.json'), 'utf8'))
    countersCall = unix(endpoint.countersSocket)
    client.connect(endpoint.url)
    await waiter.until(() => connections === 1, 'authenticated WS connection deadline', workload.deadlineMs)
    record('cold_backend_ready_ms', performance.now() - started)
    const identity = JSON.parse(readFileSync(join(root, 'first-identity.json'), 'utf8'))
    backendPid = identity.pid
    backendStart = processStart(backendPid)
    mark('empty_idle')
    await delay(workload.idleMs)

    async function create(peer: Peer, label: string): Promise<Running> {
      const nonce = peer.logPath ? randomBytes(16).toString('hex') : ''
      if (peer.logPath) writeFileSync(join(root, 'g1e', `${peer.pane}.nonce`), nonce)
      const start = performance.now()
      const created = await request<{ terminal_session_id: string; pid: number }>('terminal.create', {
        pane_id: peer.pane, agent_key: peer.vendor, cwd: peer.workspace,
        command: peer.wrapped ? buildAgentPaneCommand(endpoint.shell, [peer.commandLine]) : peer.command,
        cols: 100, rows: 30, create_generation: `${peer.pane}-generation`,
        ...(peer.logPath ? { output_log_file: peer.logPath } : {}),
        metadata: { workspace_path: peer.workspace, session_marker: `at-pane:${peer.pane}`, ...(peer.vendor === 'claude' ? { explicit_session_id: peer.pane } : {}) },
      })
      const tid = created.terminal_session_id
      sessions.push(tid)
      const terminal: ProofTerminal = { tid, pane: peer.pane, vendor: peer.vendor, label, createPid: created.pid, peerPid: 0 }
      createdTerminals.push(terminal)
      record(`${label}_ack_ms`, performance.now() - start)
      let inode: [number, number] = [0, 0]
      if (peer.logPath) { const info = statSync(peer.logPath, { bigint: true }); inode = [Number(info.dev), Number(info.ino)] }
      const tracker = new BurstTracker(count)
      const stream = shellStreams.get(tid) ?? new StreamBuffer()
      shellStreams.delete(tid)
      const running: Running = { ...peer, tid, pid: 0, sessionId: '', nonce, stream: new StreamBuffer((at, chunk) => tracker.onChunk(at, chunk)), burst: tracker, inodeAtCreate: inode, origin: null, exitAt: null, deadSeenAt: null, finalSeen: false }
      if (stream.length) running.stream.onChunk(performance.now(), stream.toBuffer())
      streams.set(tid, running)
      await running.stream.waitFor(Buffer.from('BASELINE_READY '), `child READY deadline (${peer.vendor})`, workload.deadlineMs)
      record(`${label}_ready_ms`, performance.now() - start)
      await running.stream.until((buffer) => buffer.includes('\n', buffer.indexOf('BASELINE_READY ')), `READY line deadline (${peer.vendor})`, workload.deadlineMs)
      const text = running.stream.toBuffer().toString('utf8')
      const observed = JSON.parse(text.split('BASELINE_READY ')[1].split('\n')[0].split('\r')[0])
      if (JSON.stringify(observed.argv) !== JSON.stringify(peer.argv)) throw new Error('peer argv differs from the launch')
      if (observed.cwd !== peer.workspace || observed.home !== endpoint.home || observed.providerKeys.length || observed.echoDisabled !== true) throw new Error('peer environment differs from the isolated launch')
      if (peer.vendor === 'claude') {
        if (observed.injected.mcp !== true || typeof observed.injected.skills !== 'boolean') throw new Error('claude launch injection missing')
        if (!observed.injected.skills) baselineWarnings.push(`claude skills injection missing: ${peer.pane}`)
      } else if (JSON.stringify(observed.injected) !== JSON.stringify(peer.vendor === 'opencode' ? { mcp: true, push: true } : {})) throw new Error('peer injection differs')
      if (!(observed.pid > 0)) throw new Error('peer pid missing')
      terminal.peerPid = observed.pid
      running.pid = observed.pid
      running.sessionId = peer.vendor === 'opencode' ? `ses_${peer.pane}` : peer.pane
      if (peer.vendor === 'claude') identifiedSessions.set(peer.pane, running.sessionId)
      return running
    }

    mark('shell_startup')
    for (const [index, shell] of (endpoint.shells as Peer[]).entries()) {
      const shellPeer = await create(shell, index === 0 ? 'first_shell' : 'warm_shell')
      await request('terminal.kill', { terminal_session_id: shellPeer.tid })
    }
    const usable = coldToFirstUsable(latencies)
    if (usable !== null) (latencies.cold_to_first_usable_ms ??= []).push(usable)

    mark('agent_startup')
    peers = await Promise.all((endpoint.peers as Peer[]).map(async (peer) => {
      const running = await create(peer, 'agent')
      // Release gate (E2 section 3 item 4c): the exact marker once on the renderer stream, two stable counter reads, then release; the log is not touched.
      await running.stream.waitFor(startLine(running.nonce), `ledger start marker deadline (${peer.vendor})`, workload.deadlineMs)
      const origin = await readStable(async () => counters(await countersCall({ op: 'snapshot', session: running.tid })), 8)
      running.origin = { counters: origin.counters, stable: origin.stable }
      writeFileSync(join(root, 'g1e', `${running.pane}.release`), 'go')
      return running
    }))
    mark('live_idle')
    await delay(workload.idleMs)

    async function ack(peer: Running, text: string, label: string, needle: Buffer): Promise<void> {
      const waiting = peer.stream.expect(needle, performance.now(), 'exact child ACK deadline', workload.deadlineMs)
      await request('terminal.input', { terminal_session_id: peer.tid, data: `${text}\r` })
      record(label, await waiting)
    }
    const ioNeedle = (round: number): Buffer => Buffer.from(`BASELINE_ACK ${round}:${workload.input}\n`, 'utf8')
    mark('input_output')
    await Promise.all(peers.map(async (peer) => {
      for (let round = 0; round < workload.ioRounds; round++) await ack(peer, `${round}:${workload.input}`, 'io_ms', ioNeedle(round))
    }))

    mark('burst')
    await Promise.all(peers.map(async (peer) => {
      for (let round = 0; round < burstRounds(count); round++) {
        const kk = String(round).padStart(2, '0')
        const endpointSeen = peer.stream.waitFor(doneLine(round), `burst completion deadline (round ${kk})`, workload.deadlineMs)
        const firstLine = peer.stream.waitFor(Buffer.from(`BASELINE_BURST r${kk} 0000 `), `first burst frame deadline (round ${kk})`, workload.deadlineMs)
        peer.burst.markSend(round, performance.now())
        await request('terminal.input', { terminal_session_id: peer.tid, data: `burst r${kk}\r` })
        await firstLine
        await ack(peer, `during-burst-r${kk}`, 'burst_input_ms', Buffer.from(`BASELINE_ACK during-burst-r${kk}\n`))
        await endpointSeen
      }
    }))
    for (const peer of peers) {
      const verdict = peer.burst.result()
      if (verdict.kind !== 'pass' || verdict.latencies!.some((value) => value === null)) throw new Error(`burst endpoint check failed for ${peer.vendor}: ${verdict.kind} ${verdict.why}`)
      for (const value of verdict.latencies!) record('burst_ms', value as number)
    }

    mark('observation')
    await Promise.all(peers.map(async (peer) => {
      await request('terminal.resize', { terminal_session_id: peer.tid, cols: 120, rows: 40 })
      const initial = peer.stream.waitFor(Buffer.from('BASELINE_INITIAL_WRITE\n'), 'initial fixture write deadline', workload.deadlineMs)
      await request('terminal.input', { terminal_session_id: peer.tid, data: 'observe-initial\r' })
      await initial
      if (peer.vendor === 'opencode') {
        const start = performance.now()
        try {
          await waiter.until(() => events.some((event) => matchesSessionDetection(event, peer)), 'exact native session detection deadline', workload.deadlineMs)
          identifiedSessions.set(peer.pane, peer.sessionId)
          observationOutcomes.push({ pane: peer.pane, vendor: peer.vendor, kind: 'session_detection', status: 'passed', latencyMs: performance.now() - start })
        } catch (error) { observationFailure(peer, 'session_detection', error) }
      }
      await delay(workload.observationSettleMs)
      const start = performance.now()
      await request('terminal.input', { terminal_session_id: peer.tid, data: 'observe\r' })
      const turn = (event: { type: string; payload: Record<string, unknown> }): boolean => event.type === 'agent.activity' && event.payload.pane_id === peer.pane && event.payload.event_type === 'turn_complete'
      try {
        await waiter.until(() => events.some(turn), 'attributed observation deadline', workload.deadlineMs)
        const completion = events.find(turn)!
        if (peer.vendor === 'claude') record('observation_ms', completion.at - start)
        if (completion.payload.text !== workload.reply || completion.payload.vendor !== peer.vendor || completion.payload.workspace_path !== peer.workspace) throw new Error('observation content differs')
        if (peer.vendor === 'opencode') identifiedSessions.set(peer.pane, peer.sessionId)
        observationOutcomes.push({ pane: peer.pane, vendor: peer.vendor, kind: 'activity', status: 'passed', latencyMs: completion.at - start })
      } catch (error) { observationFailure(peer, 'activity', error) }
    }))
    type Snapshot = { global: { all_time: { input: number; output: number } }; workspace: { cumulative: { totals: { input: number; output: number } }; live_by_session: Record<string, { input: number; output: number }> } }
    await Promise.all(peers.map(async (peer) => {
      try {
        const deadline = performance.now() + workload.deadlineMs
        let ready = false
        while (!ready && performance.now() < deadline) {
          const snapshot = await request<Snapshot>('tokens.snapshot', { workspace_path: peer.workspace })
          tokenSnapshots[peer.pane] = snapshot
          ready = hasExactLiveTotals(snapshot.workspace.live_by_session, identifiedSessions.get(peer.pane))
          if (!ready) await delay(20)
        }
        if (!ready) throw new Error('identified native session entry never reached the observed log totals deadline')
        observationOutcomes.push({ pane: peer.pane, vendor: peer.vendor, kind: 'live_totals', status: 'passed' })
      } catch (error) { observationFailure(peer, 'live_totals', error) }
    }))

    mark('reconnect')
    const reconnectStart = performance.now()
    client.reconnectNow('baseline transport loss')
    await waiter.until(() => connections === 2, 'reconnect deadline', workload.deadlineMs)
    const ids = peers.map((peer) => peer.tid)
    const attached = await request<{ alive: string[]; dead: string[] }>('terminal.reattach', { terminal_session_ids: ids })
    if (JSON.stringify([...attached.alive].sort()) !== JSON.stringify([...ids].sort()) || attached.dead.length) throw new Error('reattach did not report every peer alive')
    await Promise.all(peers.map((peer) => {
      const needle = Buffer.from(`BASELINE_ACK ${JSON.stringify({ pid: peer.pid, text: 'after-reconnect' })}\n`, 'utf8')
      return ack(peer, 'after-reconnect', 'reconnect_io_ms', needle)
    }))
    record('reconnect_recovery_ms', performance.now() - reconnectStart)

    // A2 (assignment 2): FINAL after the LAST byte-writing phase, so the ledger and the log identity cover the whole stream. Harness-only phase: it is no resource phase.
    mark('resize_ack')
    const peerFiles = new Map<string, PeerFile>()
    const closes = new Map<string, { counters: any; stable: boolean }>()
    await Promise.all(peers.map(async (peer) => {
      const seen = peer.stream.until((buffer) => { const at = buffer.indexOf('BASELINE_FINAL:'); return at >= 0 && finalLine(buffer.subarray(at)) !== null }, 'FINAL line deadline', workload.deadlineMs)
      await request('terminal.input', { terminal_session_id: peer.tid, data: 'g1e-final\r' })
      await seen
      peer.finalSeen = true
      closes.set(peer.tid, await readStable(async () => counters(await countersCall({ op: 'snapshot', session: peer.tid })), 8))
      const receiptPath = join(root, 'g1e', `${peer.pane}.peer.json`)
      await untilFile(receiptPath, 'peer receipt deadline', workload.deadlineMs, () => null)
      peerFiles.set(peer.tid, JSON.parse(readFileSync(receiptPath, 'utf8')))
    }))
    // C12 (A1): 20 report-only resize probes on peer 0, after the last resource phase and before the kill. The latency is request send -> response arrival.
    const probe = peers[0]
    for (let n = 0; n < 20; n++) {
      const sent = performance.now()
      await request('terminal.resize', { terminal_session_id: probe.tid, cols: 100 + (n % 2 ? 20 : 0), rows: 30 + (n % 2 ? 10 : 0) })
      record('resize_ack_ms', performance.now() - sent)
    }

    mark('kill')
    const killStart = performance.now()
    await Promise.all(peers.map((peer) => request('terminal.kill', { terminal_session_id: peer.tid })))
    let dead: string[] = []
    const killDeadline = performance.now() + workload.deadlineMs
    while (dead.length !== ids.length && performance.now() < killDeadline) {
      dead = (await request<{ dead: string[] }>('terminal.reattach', { terminal_session_ids: ids })).dead
      const seenAt = Date.now()
      // The log final check's trigger. The `terminal.exit` WS event reaches only the connection that still OWNS the session (app.py `_active_emit`: a detached pane drops it; 1 of 6 reached the client in
      // the first dry run), so it cannot be the trigger. A session reported dead by `terminal.reattach` is already out of the registry, and both close paths close() the log BEFORE the registry pop
      // (terminals.py `_finish`, cli_runtime.py `_publish_exit`): the same ordering guarantee, and the first inspection happens after it.
      for (const peer of peers) if (peer.deadSeenAt === null && dead.includes(peer.tid)) peer.deadSeenAt = seenAt
      if (dead.length !== ids.length) await delay(20) // the kill-reap latency is the reattach that first reports every peer dead; this step is the existing 06 probe cadence
    }
    if (JSON.stringify([...dead].sort()) !== JSON.stringify([...ids].sort())) throw new Error('kill did not reap every peer')
    record('kill_reap_ms', performance.now() - killStart)
    mark('empty_started_idle')
    await delay(workload.idleMs)

    // After-exit checks: terminal.exit of every peer received, then the log final check (inventory + two stable reads) and the text identity.
    if (peers.some((peer) => peer.deadSeenAt === null)) throw new Error('a peer was never observed dead')
    const ready = (existsSync(join(root, 'runtime-receipts.jsonl')) ? readFileSync(join(root, 'runtime-receipts.jsonl'), 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line)) : []).find((entry) => entry.event === 'ready' && entry.owner_pid === backendPid)
    const usage = await countersCall({ op: 'usage' })
    const logLedgers: unknown[] = []
    const finals: unknown[] = []
    let streamBytes = 0
    for (const peer of peers) {
      const wholeStream = peer.stream.toBuffer()
      const peerBytes = peerTextAfterMarker(wholeStream, peer.nonce)
      if (!peerBytes) throw new Error(`peer ${peer.index}: the marker or the FINAL line is not on the renderer stream exactly as required`)
      streamBytes += peerBytes.length
      const peerFile = join(root, 'g1e', `${peer.pane}.peerbytes`)
      writeFileSync(peerFile, peerBytes)
      const finalDocument = JSON.parse(helper(spec.python, ['log-final', mode, peer.logPath!, String(backendPid), mode === 'rust-shell' ? String(ready?.pid ?? '') : '-', String(peer.deadSeenAt)]))
      finals.push(finalDocument.record)
      const identityRecord = JSON.parse(helper(spec.python, ['log-identity', peer.logPath!, peerFile, peer.nonce, ...expectedWindowIds(peer.index, burstRounds(count))]))
      const second = finalDocument.record.reads[1]
      const close = closes.get(peer.tid)!
      if (!close.stable || !peer.origin?.stable) throw new Error(`peer ${peer.index}: the reader counters were not stable across two reads`)
      logLedgers.push(ledgerRecord({
        stream: wholeStream, nonce: peer.nonce, peerIndex: peer.index, burstRounds: burstRounds(count), session: peer.tid, pane: peer.pane, origin: peer.origin, close: close.counters, peerReceipt: peerFiles.get(peer.tid)!,
        logIdentity: identityRecord,
        logFile: { regular: second.regular, dev: second.dev, ino: second.ino, inodeAtCreate: peer.inodeAtCreate, size: second.size, siblingExists: finalDocument.siblingExists, logSentUsed: usage.log_sent_calls > 0 },
      }))
    }
    ledgers = logLedgers
    logFinals = finals
    const rawLedger = mode === 'rust-shell' ? (await countersCall({ op: 'control_ledger' })).ledger : null
    controlLedger = mapControlLedger(rawLedger, streamBytes)
    writeFileSync(join(root, 'g1e', 'ts-final.json'), JSON.stringify({ sessions, pythonPtySpawns: usage.python_pty_spawns, controlLedger: rawLedger }))
    backendEnd = processStart(backendPid)

    mark('persistence_restart')
    const restartStart = performance.now()
    driver.stdin.write('restart\n')
    await untilFile(join(root, 'restarted.json'), 'durable backend restart deadline', 60_000, () => (exitCode !== undefined ? `driver exited: ${log}` : null))
    client.connect(JSON.parse(readFileSync(join(root, 'restarted.json'), 'utf8')).url)
    await waiter.until(() => connections === 3, 'restarted backend WS authentication deadline', workload.deadlineMs)
    for (const peer of peers) {
      const snapshot = await request<Snapshot>('tokens.snapshot', { workspace_path: peer.workspace })
      tokenSnapshots[`restart-${peer.pane}`] = snapshot
      if (JSON.stringify([snapshot.global.all_time.input, snapshot.global.all_time.output]) !== JSON.stringify([12 * count, 3 * count])) throw new Error('durable global totals differ after restart')
      if (JSON.stringify([snapshot.workspace.cumulative.totals.input, snapshot.workspace.cumulative.totals.output]) !== JSON.stringify([12, 3])) throw new Error('durable workspace totals differ after restart')
    }
    record('persistence_restart_ms', performance.now() - restartStart)
    mark('finished')
    passed = phaseOutcomes.observation !== 'failed'
    if (!passed) failure = failures.join('; ')
  } catch (error) {
    failure = redactDiagnostic(error instanceof Error ? error.message : String(error))
    phaseOutcomes[phases.at(-1)!.name] = 'failed'
    failures.push(`${mode}/${count}/${repeat}: ${failure}`)
  } finally {
    // An attempt that died early still has a backend: read its end identity while it lives, so a failed attempt is `invalid`, never mistaken for an isolation breach.
    if (!backendEnd && backendPid > 0) backendEnd = processStart(backendPid)
    client.dispose('g1e attempt finished')
    driver.stdin.end('\n')
    try {
      await waiter.until(() => exitCode !== undefined, 'driver shutdown deadline', 60_000)
      if (exitCode !== 0) throw new Error(`driver exit ${exitCode}: ${redactDiagnostic(log).slice(-400)}`)
      phaseOutcomes.cleanup = 'passed'
    } catch (error) {
      passed = false
      phaseOutcomes.cleanup = 'failed'
      const detail = redactDiagnostic(error instanceof Error ? error.message : String(error))
      failure = `${failure ?? ''}; cleanup: ${detail}`
      failures.push(`${mode}/${count}/${repeat}: cleanup: ${detail}`)
    }
  }
  let resourcesJsonl = ''
  try {
    const identity = JSON.parse(readFileSync(join(root, 'first-identity.json'), 'utf8'))
    resourcesJsonl = readFileSync(join(root, 'resources.jsonl'), 'utf8')
    const samples = resourcesJsonl.trim().split('\n').map((line): Sample => JSON.parse(line))
    if (!samples.length || !samples.every((sample) => sample.generation === 'first' && sample.backend.pid === identity.pid && sample.backend.created === identity.created)) throw new Error('resource samples do not all carry the first backend identity')
    ckProof = existsSync(join(root, 'g1e', 'ck-proof.json')) ? JSON.parse(readFileSync(join(root, 'g1e', 'ck-proof.json'), 'utf8')) : null
    const final = finalizeEvidence({
      mode, cleanupPassed: phaseOutcomes.cleanup === 'passed', matched: true,
      proofStep: () => {
        const receiptPath = join(root, 'runtime-receipts.jsonl')
        const receipts = existsSync(receiptPath) ? readFileSync(receiptPath, 'utf8').trim().split('\n').filter(Boolean).map((line) => JSON.parse(line)) : []
        const readyReceipt = receipts.find((entry) => entry.event === 'ready' && entry.owner_pid === identity.pid)
        // V7 item 2: on every Rust-arm attempt the version string of the `ready` line must equal the one F0 recorded from its readiness probe.
        if (mode === 'rust-shell') readyCheck = readyVersionCheck(spec.expectedReadyVersion, readyReceipt?.version)
        const verdict = checkRuntimeProof({
          mode, backend: identity, receipts: firstGenerationReceipts(receipts, identity.pid), samples,
          expectedSha256: mode === 'rust-shell' ? spec.freeze.sidecarSha256 : null,
          recomputedSha256: readyReceipt?.executable && existsSync(readyReceipt.executable) ? sha256(readFileSync(readyReceipt.executable)) : null,
          terminals: createdTerminals,
          claude: peers.filter((peer) => peer.vendor === 'claude').map((peer) => ({
            pane: peer.pane, tid: peer.tid,
            activityPassed: observationOutcomes.some((item) => item.pane === peer.pane && item.kind === 'activity' && item.status === 'passed'),
            liveTotalsPassed: observationOutcomes.some((item) => item.pane === peer.pane && item.kind === 'live_totals' && item.status === 'passed'),
          })),
          claudeProjectsDir: join(root, 'home/.claude/projects'),
        })
        const merged = mergeCoverage(verdict, checkResourceCoverage({ mode, samples, phases, phaseOutcomes }))
        // Item 2 (CK accounting) and the Python-PTY-unused check come from the driver's `trial_proof.prove`; a missing or failed one makes the proof fail.
        const ckFailures = mode === 'rust-shell' ? (ckProof === null ? ['ck: the driver wrote no ck-proof'] : ckProof.failures.map((text: string) => `ck: ${text}`)) : []
        return ckFailures.length ? { ...merged, ok: false, failures: [...merged.failures, ...ckFailures], facts: { ...merged.facts, ckProof: ckProof?.items ?? null } } : { ...merged, facts: { ...merged.facts, ckProof: ckProof?.items ?? null } }
      },
    })
    evidenceValid = final.evidenceValid
    proof = final.proof
    if (mode === 'rust-shell' && (readyCheck === null || !(readyCheck as ReadyVersionCheck).match)) {
      // A different sidecar ready-line version is a different binary than the one F0 recorded: the attempt is evidence-invalid and the run stops (V7 item 3).
      passed = false
      evidenceValid = false
      stopReason = 'toolchain-mismatch'
      failures.push(`${mode}/${count}/${repeat}: toolchain-mismatch: the sidecar ready-line version is not F0's`)
      failure = `${failure ?? ''}; toolchain-mismatch: ready-line version`
    }
    if (final.error !== null) { passed = false; failures.push(`${mode}/${count}/${repeat}: runtime proof step: ${redactDiagnostic(final.error)}`); failure = `${failure ?? ''}; runtime proof step: ${redactDiagnostic(final.error)}` }
    else if (final.proof && !final.proof.ok) { passed = false; failures.push(`${mode}/${count}/${repeat}: runtime proof: ${redactDiagnostic(final.proof.failures.join('; '))}`); failure = `${failure ?? ''}; runtime proof: ${redactDiagnostic(final.proof.failures.join('; '))}` }
  } catch (error) {
    passed = false
    evidenceValid = false
    const detail = redactDiagnostic(error instanceof Error ? error.message : String(error))
    failure = `${failure ?? ''}; resource proof: ${detail}`
    failures.push(`${mode}/${count}/${repeat}: resource proof: ${detail}`)
  }
  const receipt = {
    schema: 'acr-g1e-trial/1', method: 'g1e', methodRevision: spec.freeze.methodRevision, kind: spec.kind, selectedRuntime: mode, count, repeat,
    measuring: spec.kind === 'measured' && spec.warmup !== true, warmup: spec.warmup === true, slot: spec.slot, firstArm: spec.firstArm, freezeSha256: spec.freeze.sha256, evidenceRevision: spec.freeze.evidenceRevision,
    expectedSidecarSha256: mode === 'rust-shell' ? spec.freeze.sidecarSha256 : null, freezeCheckedInputs: spec.freeze.checkedInputs,
    fixtureRegistrySha256: spec.fixtureRegistrySha256, logPolicySha256: spec.logPolicySha256,
    backend: { pid: backendPid, start: backendStart }, backendEnd: { pid: backendPid, start: backendEnd },
    passed, evidenceValid, harnessRescued: false, failure, stopReason, toolchain: receiptToolchain(spec.toolchain, mode === 'rust-shell' ? readyCheck : null),
    latencies, phases, phaseOutcomes, observationOutcomes, baselineWarnings,
    peerIdentities: peers.map(({ vendor, pane, tid, pid, sessionId }) => ({ vendor, pane, tid, pid, fixtureSessionId: sessionId, identifiedSessionId: identifiedSessions.get(pane) ?? null })),
    createdTerminals, proof, ledgers, logFinals,
    burstChecks: peers.map((peer) => { const verdict = peer.burst.result(); return { peer: peer.index, kind: verdict.kind, rounds: burstRounds(count), why: verdict.why } }),
    controlLedger, ckProof, exitTrigger: 'terminal.reattach reports the session dead (the terminal.exit event is informational: it reaches only the owning connection)', exitEvents, streamViolations: peers.map((peer) => peer.stream.violations), ambientBefore, ambientAfter: ambientSnapshot(), driverExitCode: exitCode,
  }
  // A measured attempt's root holds raw measured data: it is deleted without being read, also when the driver never exited (killed first). Node's fs.rmSync, no shell.
  const disposition = rootDisposition({ kind: spec.kind, keepRequested: process.env.ACR_G1E_KEEP === '1', passed, evidenceValid, exited: exitCode !== undefined })
  if (disposition === 'remove') {
    if (exitCode === undefined) driver.kill('SIGKILL')
    rmSync(root, { recursive: true, force: true })
  }
  void reports
  return { receipt, resourcesJsonl, failures }
}
